#include<bits/stdc++.h>

using namespace std;

int main(){
  int t;
  cin >> t;
  while(t--){
    int n,c;
    cin >> n >> c;
    c--;
    vector<string> s(n);
    vector<int> low(n,-1);
    for(int i=0;i<n;i++){
      cin >> s[i];
      for(int j=0;j<n;j++){
        if(s[i][j]=='#'){ low[j]=i; }
      }
    }
    vector<vector<int>> dp(n,vector<int>(n,0));
    for(int i=0;i<n;i++){dp[i][c]=1;}
    for(int i=n-2;i>=0;i--){
      for(int j=0;j<n;j++){
        if(dp[i][j]>0){continue;}
        bool ok=false;
        if(dp[i+1][j]>0){ok=true;}
        if(j>0 && dp[i+1][j-1]>0){ok=true;}
        if(j+1<n && dp[i+1][j+1]>0){ok=true;}
        if(ok){
          if(s[i][j]=='.'){
            dp[i][j]=1;
          }
          else{
            if(low[j]==i){
              for(int k=0;k<=i;k++){
                dp[k][j]=1;
              }
            }
          }
        }
      }
    }
    for(auto &nx : dp[0]){cout << nx;}
    cout << "\n";
  }
  return 0;
}
